fn bmat(
    top_left: Vec<f32>,
    top_right: Vec<f32>,
    bottom_left: Vec<f32>,
    bottom_right: Vec<f32>,
) -> Vec<f32> {
    // All four input vectors have the same length `n`.
    // We'll allocate a result vector of length 4*n and then
    // append each input in order.

    // Compute total capacity upfront for efficiency
    let n = top_left.len();
    let mut result = Vec::with_capacity(4 * n);

    // Extend the result with each quadrant in turn
    result.extend(top_left);
    result.extend(top_right);
    result.extend(bottom_left);
    result.extend(bottom_right);

    result
}

